query PullRequestForBranch($owner: String!, $repo: String!, $headRefName: String!, $states: [PullRequestState!]) {
	repository(owner: $owner, name: $repo) {
		pullRequests(headRefName: $headRefName, states: $states, first: 30, orderBy: { field: CREATED_AT, direction: DESC }) {
			nodes {id,author{login,...on User{id,name}},url,title,body,baseRefName,reviewRequests(first: 100) {nodes {requestedReviewer {__typename,...on User{login,name},...on Bot{login},...on Team{organization{login}name,slug}}}},labels(first:100){nodes{id,name,description,color},totalCount},milestone{number,title,description,dueOn},assignees(first:100){nodes{id,login,name,databaseId},totalCount},number,state,headRefName,isCrossRepository,headRepositoryOwner{id,login,...on User{name}}}
		}
		defaultBranchRef { name }
	}
}
